def forward_kv_ids(ids, s, kv, is_prefill, mask, pos_off):
    ew = torch.tpack_get("embed_tokens.weight")
    h = torch.tpack_index(ew, ids).reshape(1, s, 1280)
    return forward_kv_h(h, s, kv, is_prefill, mask, pos_off)

def forward_kv_embed(he, s, kv, is_prefill, mask, pos_off):
    h = he.reshape(1, s, 1280)
    return forward_kv_h(h, s, kv, is_prefill, mask, pos_off)


